142	SuccessScreen.displayName = 'SuccessScreen';
143	
144	const ErrorScreen = memo(({ message, subMessage }: { message: string, subMessage: string }) => (
145	  <div className="text-center flex flex-col items-center">
146	    <XCircle className="w-32 h-32 text-red-400 mb-8" />
