148	    <p className="text-2xl text-gray-400 mt-4">{subMessage}</p>
149	    <p className="text-sm text-gray-500 mt-8">(5秒後に自動的に戻ります)</p>
150	  </div>
151	));
152	ErrorScreen.displayName = 'ErrorScreen';
153	
154	const RegisterScreen = memo(({ message, subMessage }: { message: string, subMessage: string }) => (
155	    <div className="text-center flex flex-col items-center">
156	        <UserPlus className="w-32 h-32 text-blue-400 mb-8" />
157	        <p className="text-5xl font-bold">{message}</p>
158	        <p className="text-2xl text-gray-400 mt-4">{subMessage}</p>
159	        <p className="text-sm text-gray-500 mt-8">キャンセルするにはEscキー</p>
160	    </div>
161	));
162	RegisterScreen.displayName = 'RegisterScreen';
163	
164	
165	const QrTimer = memo(({ qrExpiry, onExpire }: { qrExpiry: number, onExpire: () => void }) => {
166	    const [remaining, setRemaining] = useState(qrExpiry - Date.now());
167	    useEffect(() => {
168	        const timer = setInterval(() => {
169	            const newRemaining = qrExpiry - Date.now();
170	            if (newRemaining <= 0) {
171	                clearInterval(timer);
172	                onExpire();
173	            }
174	            setRemaining(newRemaining);
175	        }, 1000);
176	        return () => clearInterval(timer);
177	    }, [qrExpiry, onExpire]);
178	
179	    const minutes = Math.floor(remaining / 60000);
180	    const seconds = Math.floor((remaining % 60000) / 1000).toString().padStart(2, '0');
181	
182	    return (
183	        <p className="mt-2 text-lg">有効期限: あと{minutes}分{seconds}秒</p>
184	    );
185	});
186	QrTimer.displayName = 'QrTimer';
187	
188	
189	const QrScreen = memo(({ qrToken, qrExpiry, onExpire }: { qrToken: string, qrExpiry: number, onExpire: () => void }) => {
190	    const { toast } = useToast();
191	    const url = `${process.env.NEXT_PUBLIC_APP_URL}/register/${qrToken}`;
192	
193	    const handleCopy = useCallback(() => {
194	        navigator.clipboard.writeText(url).then(() => {
195	            toast({ title: "コピーしました", description: "登録用リンクをクリップボードにコピーしました。" });
196	        }).catch(err => {
197	            console.error('Failed to copy: ', err);
198	            toast({ variant: 'destructive', title: "コピー失敗", description: "リンクのコピーに失敗しました。" });
199	        });
200	    }, [url, toast]);
201	
202	    return (
203	        <div className="text-center flex flex-col items-center">
204	            <p className="text-4xl font-bold mb-4">QRコード登録</p>
205	            <div className="bg-white p-4 rounded-lg">
206	                <Image
207	                    src={`https://api.qrserver.com/v1/create-qr-code/?size=256x256&data=${encodeURIComponent(url)}`}
208	                    width={256}
209	                    height={256}
210	                    alt="QR Code"
211	                    data-ai-hint="qr code"
212	                    priority
213	                />
214	            </div>
215	            <p className="mt-4 text-xl max-w-md">スマートフォンでQRコードを読み取り登録を完了してください。</p>
216	            <div className="mt-4 flex items-center gap-2 bg-gray-800 px-4 py-2 rounded-lg max-w-2xl">
217	                <p className="text-sm text-gray-300 font-mono break-all">{url}</p>
