222	            <QrTimer qrExpiry={qrExpiry} onExpire={onExpire} />
223	            <p className="text-sm text-gray-500 mt-4">※QR読み取り後、この画面は自動的に戻ります</p>
224	        </div>
225	    );
226	});
227	QrScreen.displayName = 'QrScreen';
228	
229	const ProcessingScreen = memo(({ state }: { state: 'loading' | 'processing' }) => (
